22: 
23:     // Obtener parámetros de la ruta
24:     const params = route.params;
25: 
26:     if (menuPermisos != null) {
27:       // Pasar tanto la URL como los parámetros a la función de verificación
28:       if (checkUrlExists(menuPermisos, path, params)) {
29:         return true;
30:       }
31:     }
32: 
33:     this.popUpManager.showErrorAlert(this.translate.instant('ERROR.rol_insuficiente_titulo'));
34:     return false;
35:   }
36: 
37:   canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
38:     return this.canActivate(route, state);
